function quedan(plazo, pasadas) {
  return plazo - pasadas;
}
console.log(quedan(72, 20));
console.log(quedan(20, 72));

function enPlazo(dias) {
  return dias <= 30;
}
console.log(enPlazo(12));
if (enPlazo(45)) {
  console.log("Bien");
} else {
  console.log("Reclamar");
}

